#!/usr/bin/env python3
"""Remove duplicate lines from a file while preserving original order."""

import argparse
import sys


def main(argv=None):
    parser = argparse.ArgumentParser(
        description="Remove duplicate lines from a file while preserving the original order."
    )
    parser.add_argument(
        "input",
        nargs="?",
        help="input file; omit to read from standard input",
    )
    parser.add_argument(
        "-o",
        "--output",
        help="output file; default is standard output",
    )
    parser.add_argument(
        "--ignore-case",
        action="store_true",
        help="compare lines case-insensitively",
    )
    args = parser.parse_args(argv)

    if args.input:
        try:
            infile = open(args.input, "r", encoding="utf-8", errors="replace")
        except OSError as exc:
            parser.error(f"cannot open input file: {exc}")
    else:
        infile = sys.stdin

    if args.output:
        try:
            outfile = open(args.output, "w", encoding="utf-8")
        except OSError as exc:
            if infile is not sys.stdin:
                infile.close()
            parser.error(f"cannot open output file: {exc}")
    else:
        outfile = sys.stdout

    seen = set()
    try:
        for line in infile:
            key = line.rstrip("\n")
            if key.endswith("\r"):
                key = key[:-1]
            if args.ignore_case:
                key = key.casefold()

            if key not in seen:
                seen.add(key)
                outfile.write(line)
    finally:
        if infile is not sys.stdin:
            infile.close()
        if outfile is not sys.stdout:
            outfile.close()


if __name__ == "__main__":
    main()

